{
  "packet_id": "H6-T04-3",
  "claim_id": "C010",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C010.component",
    "value": "Customer recontact should sample across different event paths and include both publishers and non-publishers.",
    "scope": "Consenting customers; no representativeness or prevalence-estimation guarantee is asserted.",
    "provenance": {
      "refs": [
        {
          "source_id": "P007",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span directly supplies the sampling recommendation and consent restriction without asserting representativeness."
    }
  },
  "signal_basis": {
    "component_id": "C010.signal_basis",
    "value": "Recontact gathers intended publication timing, information availability, offline preparation and stopping points across different event paths and publication outcomes. These observations are assessed for discriminating patterns, since draft saves, absent invitations or silence alone can fit multiple explanations.",
    "scope": "Qualitative comparison among consenting customers across event paths, including publishers and non-publishers; discrimination is sought rather than guaranteed.",
    "provenance": {
      "refs": [
        {
          "source_id": "P007",
          "role": "SUPPORT"
        },
        {
          "source_id": "P015",
          "role": "SUPPORT"
        },
        {
          "source_id": "P021",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited bundle identifies the recontact evidence, sampling scope, comparative purpose and ambiguity of event traces alone."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C010.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The bounded sampling recommendation is supported without requiring an additional unresolved empirical relation."
    }
  },
  "rationale": "Sampling across event paths and both publication outcomes provides relevant contrasts for examining competing explanations and avoids restricting inquiry to a single outcome. This licenses the stated methodological recommendation without implying representative frequencies or guaranteed causal identification.",
  "uncertainty": "Consent and response selection can limit what these comparisons reveal, but the claim makes no population-representativeness or prevalence-estimation promise.",
  "anomalies": []
}
